                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append((color, cells))

    # The irregular filled mass is recolored to match the thin, straight
    # color marker elsewhere in the image.
    def box(obj):
        cells = obj[1]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        return r1-r0+1, c1-c0+1

    target = max(objects, key=lambda o: len(o[1]))
    # Choose the smallest straight-line object as the color cue.
    cues = []
    for obj in objects:
        if obj is target:
            continue
        bh, bw = box(obj)
        if bh == 1 or bw == 1:
            cues.append(obj)
    cue = min(cues, key=lambda o: len(o[1])) if cues else target

    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = cue[0]
    return out
